<?php
// dashes - no em dash or en dash in a touched file (the owner, 2026-11-03): every file a change touches is read whole, so
// the library is cleaned file by file. Code that needs the characters writes them escaped ("\u{2014}"); a record (.md, .txt)
// keeps them only inside `code` and fences. Generated files are skipped: their sources carry the text.
// Usage: php tools/dashes.php [--staged | --commit | --changed | FILE...] - --staged for the hook, --commit for the workflow.

const DASHES_ROOT = __DIR__ . '/..';
const DASHES_RE = "~[\u{2014}\u{2013}]~u";
const DASHES_SOURCE_RE = '~\.(?:php|js|mjs|css|sh|html?|json|md|txt|yml)\z~i';
const DASHES_SKIP_RE = '~(?:^|/)(?:dist|node_modules|vendor|\.code/research)/|\.min\.(?:js|css)\z|(?:^|/)(?:LICENSE|LICENCE|NOTICE|COPYING)[^/]*\z'
	. '|(?:^|/)feedback-no-em-dash\.md\z|^llms(?:-full)?\.txt\z~i';
const DASHES_GENERATED = ['Generated by tools/', 'do not edit'];

/**
 * Lines of $text that write a dash where the rule forbids it: [line, text]; a record may keep one in code spans and fences.
 * @return list<array{0: int, 1: string}>
 */
function DASHES__Check(string $file, string $text): array
{
	$record = preg_match('~\.(?:md|txt)\z~i', $file) === 1;
	$found = [];
	$fence = false;
	$span = false;
	foreach (explode("\n", $text) as $i => $line) {
		if ($record && str_contains($line, 'feedback-no-em-dash')) {
			continue;
		}
		if ($record && preg_match('~^\s*```~', $line) === 1) {
			$fence = !$fence;
			continue;
		}
		if ($fence) {
			continue;
		}
		$plain = $line;
		if ($record) {
			$plain = '';
			foreach (explode('`', $line) as $tick => $part) {
				$span = $tick > 0 ? !$span : $span;
				$plain .= $span ? '' : $part;
			}
		}
		if (preg_match(DASHES_RE, $plain) === 1) {
			$found[] = [$i + 1, trim($line)];
		}
	}
	return $found;
}

/** True when the rule reads this file: a source or a record, not third-party, built or generated by a tool. */
function DASHES__IsSource(string $file, string $text): bool
{
	if (preg_match(DASHES_SOURCE_RE, $file) !== 1 || preg_match(DASHES_SKIP_RE, $file) === 1 || str_contains($text, "\0")) {
		return false;
	}
	$head = substr($text, 0, 400);
	return array_filter(DASHES_GENERATED, static fn(string $mark): bool => str_contains($head, $mark)) === [];
}

/** The planted shapes: every forbidden dash is found, every allowed one and every skipped file is left alone; '' when all hold. */
function DASHES__Selftest(): string
{
	$em = "\u{2014}";
	$en = "\u{2013}";
	$hit = static fn(string $file, string $text): bool => DASHES__Check($file, $text) !== [];
	$cases = [
		'a comment' => $hit('a.js', "// a note $em here\n"),
		'a string literal, en dash' => $hit('a.php', "<?php\n\$s = 'x $en y';\n"),
		'a css comment' => $hit('a.css', "/* one $em two */\n"),
		'a range in a record' => $hit('n.md', "range 1.4{$en}1.8\n"),
		'after a closed span' => $hit('n.md', "`a` then $em\n"),
		'an escape in js is clean' => !$hit('a.js', "const s = '\\u2014';\n"),
		'an escape in php is clean' => !$hit('a.php', "<?php\n\$s = \"\\u{2014}\";\n"),
		'a code span is clean' => !$hit('n.md', "Code `'$em'` quoted\n"),
		'a fence is clean' => !$hit('n.md', "```\nx $em y\n```\n"),
		'a span over two lines is clean' => !$hit('n.md', "A `span\ncontinues $em` here\n"),
		'the rule line is clean' => !$hit('MEMORY.md', "- [No em dash](feedback-no-em-dash.md) - never \"$em\"\n"),
		'a hyphen is clean' => !$hit('a.css', "/* a - b, 1.4-1.8 */\n"),
		'a source is read' => DASHES__IsSource('css/btn.css', '.btn {}'),
		'a generated page is skipped' => !DASHES__IsSource('docs/btn.md', "<!-- Generated by tools/docs.php from docs/src/btn.html -->\n"),
		'llms.txt is skipped' => !DASHES__IsSource('llms.txt', 'x'),
		'a built file is skipped' => !DASHES__IsSource('dist/redz-ui.css', 'x'),
		'the rule note is skipped' => !DASHES__IsSource('.code/memory/feedback-no-em-dash.md', 'x'),
		'an image is skipped' => !DASHES__IsSource('icons/x.svg', 'x'),
	];
	$missed = array_keys(array_filter($cases, static fn(bool $ok): bool => !$ok));
	return $missed === [] ? '' : implode(' · ', $missed);
}

/**
 * The files of the run with their text: the index for --staged, HEAD against its parent for --commit, the working tree else.
 * @return array<string, string> file => text
 */
function DASHES__Files(array $argv): array
{
	$git = static fn(string $args): array => array_values(array_filter(explode("\0", (string)shell_exec('git -C ' . escapeshellarg(DASHES_ROOT) . ' ' . $args . ' 2>/dev/null'))));
	$mode = $argv[1] ?? '--changed';
	$files = match ($mode) {
		'--staged' => $git('diff --cached --name-only -z --diff-filter=ACMR'),
		'--commit' => $git('diff --name-only -z --diff-filter=ACMR HEAD~1 HEAD'),
		'--changed' => [...$git('diff HEAD --name-only -z --diff-filter=ACMR'), ...$git('ls-files -z --others --exclude-standard')],
		default => array_slice($argv, 1),
	};
	$out = [];
	foreach (array_unique($files) as $file) {
		$text = $mode === '--staged' ? (string)shell_exec('git -C ' . escapeshellarg(DASHES_ROOT) . ' show ' . escapeshellarg(':' . $file) . ' 2>/dev/null')
			: (string)@file_get_contents(DASHES_ROOT . '/' . $file);
		$out[$file] = $text;
	}
	return $out;
}

function DASHES__Main(array $argv): int
{
	$blind = DASHES__Selftest();
	if ($blind !== '') {
		fwrite(STDERR, 'dashes: the self-test did not recognize ' . $blind . "\n");
		return 1;
	}
	$read = 0;
	$found = 0;
	foreach (DASHES__Files($argv) as $file => $text) {
		if (!DASHES__IsSource($file, $text)) {
			continue;
		}
		$read++;
		foreach (DASHES__Check($file, $text) as [$line, $shown]) {
			$found++;
			fwrite(STDERR, $file . ':' . $line . '  ' . mb_substr($shown, 0, 100) . "\n");
		}
	}
	if ($found > 0) {
		fwrite(STDERR, 'dashes: ' . $found . ' in ' . $read . ' touched files - write "-", or "\u{2014}" where code needs the character' . "\n");
		return 1;
	}
	echo 'dashes: clean, ', $read, " touched files\n";
	return 0;
}

exit(DASHES__Main($argv));
